from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    p = Path(path)
    s = p.read_text(encoding='utf-8')
    if old not in s:
        raise SystemExit(f'anchor missing {path}: {old[:180]!r}')
    p.write_text(s.replace(old, new, 1), encoding='utf-8')

# 1) Extend the existing generic Moris-lazy ATK-rank slice by exactly one
# direct-damage bullet-lifetime shape. No character names and no new transaction
# system: the existing PendingTargetEffect path already matches Moris selection.
replace_once(
    'fast_engine/engine/dispatcher.py',
'''    @staticmethod\n    def _lazy_rank_target_shape_supported(effect: "CompiledEffect") -> bool:\n        """Own simple Moris lazy ATK-rank states without bullet lifetimes.\n\n        Direct-damage buffs retain the existing generic slice. Cadence is much\n        narrower: one finite positive caster-based charge-speed buff delivered\n        to the lowest-ATK base B3 at full-burst start. Recipient weapon safety\n        is a squad-level score proof, not a runtime-shape assumption.\n        """\n\n        max_stack = effect.max_stack if effect.max_stack is not None else 1.0\n''',
'''    @staticmethod\n    def _lazy_rank_one_bullet_shape_supported(effect: "CompiledEffect") -> bool:\n        """Certify one Moris-lazy rank buff lasting one recipient shot.\n\n        The first slice is deliberately narrow: one direct-damage state, top-ATK\n        excluding self, one recipient, one full-burst-start trigger and exactly\n        one bullet of lifetime. ``favorite`` is compiler metadata only.\n        """\n        params = effect.parameters\n        max_stack = effect.max_stack if effect.max_stack is not None else 1.0\n        return (\n            is_direct_damage_buff_runtime_supported(effect)\n            and effect.effect_type == "buff"\n            and effect.target_spec.mode is TargetMode.TOP_ATK_EXCL_SELF\n            and effect.target_spec.runtime_supported\n            and int(effect.target_spec.count or 0) == 1\n            and float(max_stack) == 1.0\n            and effect.max_trigger is None\n            and effect.tick_interval is None\n            and effect.duration in (None, -1, -1.0)\n            and params.get("duration_bullets") == 1\n            and set(params).issubset({"favorite", "duration_bullets"})\n            and not effect.condition_rules\n            and len(effect.triggers) == 1\n            and effect.triggers[0].mode is TriggerMode.EVENT\n            and effect.triggers[0].event_key == "full_burst_start"\n        )\n\n    @staticmethod\n    def _lazy_rank_target_shape_supported(effect: "CompiledEffect") -> bool:\n        """Own the certified Moris-lazy ATK-rank state families."""\n\n        if TriggerDispatcher._lazy_rank_one_bullet_shape_supported(effect):\n            return True\n        max_stack = effect.max_stack if effect.max_stack is not None else 1.0\n''')

replace_once(
    'fast_engine/engine/dispatcher.py',
'''    def _lazy_rank_target_runtime_supported(self, effect: "CompiledEffect") -> bool:\n        if not self._lazy_rank_target_shape_supported(effect):\n            return False\n        if effect.name:\n''',
'''    def _lazy_rank_target_runtime_supported(self, effect: "CompiledEffect") -> bool:\n        if not self._lazy_rank_target_shape_supported(effect):\n            return False\n        if (\n            self._lazy_rank_one_bullet_shape_supported(effect)\n            and not self._bullet_lifetime_runtime_safe(effect)\n        ):\n            return False\n        if effect.name:\n''')

replace_once(
    'fast_engine/engine/dispatcher.py',
'''    def _bullet_lifetime_runtime_safe(self, effect: "CompiledEffect") -> bool:\n        if effect.parameters.get("duration_bullets") is None:\n            return True\n        if not target_scope_is_static(effect.target_spec):\n            return True\n''',
'''    def _bullet_lifetime_runtime_safe(self, effect: "CompiledEffect") -> bool:\n        if effect.parameters.get("duration_bullets") is None:\n            return True\n        if self._lazy_rank_one_bullet_shape_supported(effect):\n            targets = possible_ally_targets(self.squad, effect)\n            return bool(targets) and all(\n                self.effects.dynamic_bullet_lifetime_supported(actor)\n                for actor in targets\n            )\n        if not target_scope_is_static(effect.target_spec):\n            return True\n''')

# 2) A deferred bullet lifetime is never allowed to fall back to a stale static
# Nth-shot schedule. Score ownership must register every possible recipient on a
# live cadence runtime before the first read materializes the cohort.
replace_once(
    'fast_engine/engine/effects.py',
'''            self._pending_target.pop(effect_id, None)\n            cohort = self._cohort(targets)\n            if not cohort:\n                continue\n            # Lifetimes start at activation, not at first read.  This slice does\n            # not defer duration_bullets, so scheduling from activated_at cannot\n            # create a missed post-shot expiry.\n            for target in cohort:\n''',
'''            self._pending_target.pop(effect_id, None)\n            cohort = self._cohort(targets)\n            if not cohort:\n                continue\n            if effect.parameters.get("duration_bullets") is not None:\n                unsafe = tuple(\n                    target\n                    for target in cohort\n                    if target not in self._dynamic_bullet_targets\n                )\n                if unsafe:\n                    names = ", ".join(self.squad.members[target].name for target in unsafe)\n                    raise NotImplementedError(\n                        "Fast lazy duration_bullets requires live recipient cadence: "\n                        + names\n                    )\n            # Lifetimes still start at activation.  The one-bullet lazy slice is\n            # materialized immediately before the recipient's first scored shot,\n            # then consumed by that live cadence runtime after the shot damage and\n            # post-hit signals. Static Nth-shot back-scheduling is forbidden here.\n            for target in cohort:\n''')

# 3) Register rapid candidates exactly like the existing charge bullet-lifetime
# candidates. This is sparse: actors are added only when an executable direct-
# damage bullet-lifetime effect may select them and their rapid cadence is owned.
replace_once(
    'fast_engine/engine/score.py',
'''def _dynamic_charge_score_actors(squad: CompiledSquad) -> tuple[int, ...]:\n''',
'''def _dynamic_rapid_bullet_lifetime_score_actors(\n    squad: CompiledSquad,\n) -> tuple[int, ...]:\n    actors: set[int] = set()\n    for effect in squad.effects:\n        if effect.parameters.get("duration_bullets") is None:\n            continue\n        if not is_direct_damage_buff_runtime_supported(effect):\n            continue\n        if not TriggerDispatcher.is_executable_effect(effect):\n            continue\n        for actor in _possible_ally_targets(squad, effect):\n            if _rapid_actor_score_safe(squad, actor):\n                actors.add(actor)\n    return tuple(sorted(actors))\n\n\ndef _dynamic_charge_score_actors(squad: CompiledSquad) -> tuple[int, ...]:\n''')

replace_once(
    'fast_engine/engine/score.py',
'''    actors.update(_dynamic_mg_warmup_score_actors(squad))\n    actors.update(_dynamic_force_reload_score_actors(squad))\n''',
'''    actors.update(_dynamic_mg_warmup_score_actors(squad))\n    actors.update(_dynamic_force_reload_score_actors(squad))\n    actors.update(_dynamic_rapid_bullet_lifetime_score_actors(squad))\n''')

# 4) Static score certification requires every over-approximated rank candidate
# to have a live weapon ownership proof. This intentionally accepts the same
# conservative possible-target superset used elsewhere; no observed roster names
# are encoded in production.
replace_once(
    'fast_engine/engine/score.py',
'''def _lazy_rank_target_score_safe(squad: CompiledSquad, effect) -> bool:\n    if not TriggerDispatcher._lazy_rank_target_shape_supported(effect):\n        return False\n    if (effect.stat or "") == "charge_speed_caster_based_pct":\n''',
'''def _lazy_rank_target_score_safe(squad: CompiledSquad, effect) -> bool:\n    if not TriggerDispatcher._lazy_rank_target_shape_supported(effect):\n        return False\n    if TriggerDispatcher._lazy_rank_one_bullet_shape_supported(effect):\n        candidates = _possible_ally_targets(squad, effect)\n        if not candidates or not all(\n            _charge_actor_score_safe(squad, actor)\n            or _rapid_actor_score_safe(squad, actor)\n            for actor in candidates\n        ):\n            return False\n    if (effect.stat or "") == "charge_speed_caster_based_pct":\n''')

# 5) Focused regression: public semantic trace, live one-shot consumption,
# shape boundaries, and low-level fail-closed materialization guard.
test = '''from __future__ import annotations\n\nfrom dataclasses import replace\nimport unittest\nfrom unittest.mock import patch\n\nfrom context import snapshot, spec\nfrom fast_engine.engine.burst import compile_burst_policy\nfrom fast_engine.engine.burst_runtime import BurstRuntime\nfrom fast_engine.engine.compiler import compile_moris_squad\nfrom fast_engine.engine.damage_runtime import SimpleDamageScoreSink\nfrom fast_engine.engine.dispatcher import TriggerDispatcher\nfrom fast_engine.engine.effects import ActiveEffectStore\nfrom fast_engine.engine.model import EnemyStaticProfile\nfrom fast_engine.engine.scheduler import EventScheduler\nfrom fast_engine.engine.score import StaticNormalAttackObserver, static_score_blockers\nfrom fast_engine.engine.state import StateStore\nfrom fast_engine.engine.target_scope import possible_ally_targets\n\n\nclass MirandaLazyRankBulletLifetimeTests(unittest.TestCase):\n    TEAM = "레이드_헬름아쿠아스노우"\n    ORACLE = (\n        (3.399999999999993, "스노우 화이트"),\n        (21.58333333333339, "에이다"),\n        (37.56666666666582, "스노우 화이트"),\n        (50.94999999999839, "에이다"),\n        (64.33333333333097, "스노우 화이트"),\n    )\n\n    @classmethod\n    def _compiled(cls):\n        moris = spec.build_squad(list(snapshot.SQUADS[cls.TEAM]["members"]))\n        compiled = compile_moris_squad(moris)\n        miranda = next(i for i,m in enumerate(compiled.members) if m.name == "미란다")\n        wake = next(e for e in compiled.members[miranda].effects if e.name == "웨이크업! 4")\n        return moris, compiled, wake\n\n    def test_public_shape_closes_rank_timing_blocker(self):\n        _moris, compiled, wake = self._compiled()\n        self.assertTrue(TriggerDispatcher._lazy_rank_one_bullet_shape_supported(wake))\n        self.assertEqual(wake.parameters.get("duration_bullets"), 1)\n        self.assertEqual(static_score_blockers(compiled), ())\n\n    def test_public_target_trace_and_one_shot_consumption_match_oracle(self):\n        moris, compiled, wake = self._compiled()\n        duration = 70.0\n        policy = compile_burst_policy(moris, compiled, {"duration": duration, "rng_mode": "expected"})\n        enemy = EnemyStaticProfile(defense=31784.0, duration=duration)\n        sink = SimpleDamageScoreSink(compiled, enemy)\n        activations = []\n        removals = []\n        orig_activate_one = ActiveEffectStore._activate_one\n        orig_consume = ActiveEffectStore.consume_dynamic_bullet\n\n        def traced_activate_one(store, effect, target, cohort, now, scheduler, **kwargs):\n            row = orig_activate_one(store, effect, target, cohort, now, scheduler, **kwargs)\n            if effect.effect_id == wake.effect_id:\n                activations.append((float(now), store.squad.members[target].name))\n            return row\n\n        def traced_consume(store, target, *, now, count=1):\n            removed = orig_consume(store, target, now=now, count=count)\n            if wake.effect_id in removed:\n                removals.append((float(now), store.squad.members[target].name))\n            return removed\n\n        with patch.object(ActiveEffectStore, "_activate_one", new=traced_activate_one), patch.object(ActiveEffectStore, "consume_dynamic_bullet", new=traced_consume):\n            runtime = BurstRuntime(compiled, policy, enemy, damage_sink=sink)\n            observer = StaticNormalAttackObserver(runtime, duration=duration)\n            for actor in possible_ally_targets(compiled, wake):\n                self.assertTrue(runtime.dispatcher.effects.dynamic_bullet_lifetime_supported(actor))\n            runtime.run(duration=duration, score_observer=observer)\n\n        self.assertEqual(len(activations), len(self.ORACLE))\n        for actual, expected in zip(activations, self.ORACLE):\n            self.assertAlmostEqual(actual[0], expected[0], places=9)\n            self.assertEqual(actual[1], expected[1])\n        self.assertEqual([name for _,name in removals], [name for _,name in self.ORACLE])\n        self.assertEqual(len(removals), len(self.ORACLE))\n        for (activated, name), (expired, expired_name) in zip(activations, removals):\n            self.assertEqual(name, expired_name)\n            self.assertGreater(expired, activated)\n\n    def test_neighboring_bullet_rank_shapes_remain_fail_closed(self):\n        _moris, _compiled, wake = self._compiled()\n        two = replace(wake, parameters={**wake.parameters, "duration_bullets": 2})\n        timed = replace(wake, duration=5.0)\n        two_targets = replace(wake, target_spec=replace(wake.target_spec, count=2))\n        self.assertFalse(TriggerDispatcher._lazy_rank_one_bullet_shape_supported(two))\n        self.assertFalse(TriggerDispatcher._lazy_rank_one_bullet_shape_supported(timed))\n        self.assertFalse(TriggerDispatcher._lazy_rank_one_bullet_shape_supported(two_targets))\n\n    def test_deferred_bullet_target_without_live_cadence_fails_closed(self):\n        _moris, compiled, wake = self._compiled()\n        store = ActiveEffectStore(compiled, StateStore.from_compiled_squad(compiled))\n        scheduler = EventScheduler()\n        target = next(i for i,m in enumerate(compiled.members) if m.name == "스노우 화이트")\n        store.attach_lazy_target_resolver(lambda _effect, _activated, _now: (target,))\n        store.defer_target_group(wake, 3.4, scheduler)\n        with self.assertRaisesRegex(NotImplementedError, "lazy duration_bullets requires live recipient cadence"):\n            store.sum_stat(target, "crit_rate", now=3.4)\n\n\nif __name__ == "__main__":\n    unittest.main()\n'''
Path('fast_engine/tests/test_damage_miranda_lazy_rank_bullet_lifetime.py').write_text(test, encoding='utf-8')

print('staged Miranda lazy rank one-bullet lifetime semantics')
